          let u, w;
          if (mode === "beamZ") { u = nz !== 0 ? x : z; w = ny !== 0 ? x : y; }
          else if (mode === "beamX") { u = nx !== 0 ? z : x; w = ny !== 0 ? z : y; }
          else if (ny !== 0) { u = x; w = -z; }
