      l.beginPath(); l.moveTo(x0 - w0 / 2, y0); l.lineTo(x0 + w0 / 2, y0); l.lineTo(x1 + w1 / 2, 204); l.lineTo(x1 - w1 / 2, 204); l.closePath(); l.fill(); l.stroke();
