      const KW = [[0.06, 1.5, -0.02], [0.16, 1.5, -0.1], [0.26, 1.58, -0.2], [0.32, 1.76, -0.27], [0.33, 1.96, -0.23], [0.31, 2.12, -0.1], [0.28, 2.18, 0.1], [0.26, 2.18, 0.38], [0.245, 2.17, 0.62], [0.24, 2.16, KAP_Z]];
