        for (let i = 0; i < n; i++) { seed[3 * i] = hash(i * 1.7) - 0.5; seed[3 * i + 1] = 0.6 + 0.4 * hash(i * 2.3); seed[3 * i + 2] = hash(i * 3.1) - 0.5; phase[i] = hash(i * 5.3); }
