          const eE = eagleAt(grp, X + 3.55, stepY(k), stepZ(k) - 0.2, -HP, 0.85), eW = eagleAt(grp, X - 3.55, stepY(k), stepZ(k) - 0.2, -HP, 0.85);   // 1.0.1-L: 0.2 back, so the lion's long arm passes before the eagle
