        elNum.textContent = "";
        elTtl.textContent = "סוף המצגת";
        elSub.style.display = "none";
        elVs.textContent = "";
        elTxt.textContent = "השיטות, השכבות והמתגים שהיו לפני המצגת הוחזרו, וחזרנו למבט הכללי. אפשר להמשיך לבד בלוח הבקרה, או להתחיל שוב.";
        elCaps.textContent = "";
